'use strict';
let encyclopediaTab='crew',encyclopediaSearch='',mobileZoom=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function bind(id,fn){const el=[...document.querySelectorAll('[id="'+id+'"]')].pop();if(el)el.onclick=fn}
function riverArt(x,y){const d=directionAt(x,y),out=[50+d[0]*51,50+d[1]*51],incoming=[];for(const[dx,dy]of DIR){const nx=x+dx,ny=y+dy;if(!inside(nx,ny)||tile(nx,ny)!=='water')continue;const f=directionAt(nx,ny);if(nx+f[0]===x&&ny+f[1]===y)incoming.push([50+dx*51,50+dy*51])}const paths=(incoming.length?incoming:[[50,50]]).map(([ix,iy])=>`M${ix} ${iy} Q50 50 ${out[0]} ${out[1]}`),rotation=DIR.findIndex(v=>v[0]===d[0]&&v[1]===d[1])*90;return `<svg class="river-art" viewBox="0 0 100 100" aria-hidden="true">${paths.map(p=>`<path d="${p}" fill="none" stroke="#8ebcbd" stroke-width="39" stroke-linecap="round"/><path d="${p}" fill="none" stroke="#b7ded8" stroke-width="27" stroke-linecap="round"/><path class="river-flow" d="${p}" fill="none" stroke="#e5efda" stroke-opacity=".6" stroke-width="2" stroke-dasharray="8 18"/>`).join('')}<path d="m43 54 7-8 7 8" transform="rotate(${rotation} 50 50)" fill="none" stroke="#4a9195" stroke-width="3" stroke-linecap="round"/></svg>`}
function terrainArt(x,y){const t=tile(x,y);return t==='water'?riverArt(x,y):groundArt(x,y,t)}
function unitArt(u){return `<span class="unit-sprite" data-piece="${u.id}" style="--idle-delay:-${(u.x*7+u.y*3)%9/3}s">${portrait(u.role,u.team==='enemy')}<span class="unit-badge" style="background:${u.team==='enemy'?'#b86750':ROLES[u.role]?.color||'#719688'}">${esc(u.team==='enemy'?ENEMIES[u.role]?.icon:ROLES[u.role]?.icon)}</span><span class="hp">${'<b></b>'.repeat(u.hp)}</span>${u.shield?'<span class="status-shield">⬡</span>':''}${u.root?'<span class="status-root">❧</span>':''}${u.charm?'<span class="status-charm">♫</span>':''}</span>`}
function directionsHTML(u){const a=ROLES[u?.role]?.action;if(!['channel','dig','remotePush','conveyor','rotate','weather'].includes(a))return '';if(a==='weather')return `<div class="direction-label">Weather for the next round</div><div class="weather-options">${['rain','frost','wind','storm'].map(w=>`<button class="direction ${weatherChoice===w?'on':''}" data-weather="${w}">${{rain:'☂',frost:'❄',wind:'≋',storm:'ϟ'}[w]} ${w}</button>`).join('')}</div>`;return `<div class="direction-label">${a==='channel'||a==='dig'?'New current direction':'Effect direction'}</div><div class="direction-options" role="group" aria-label="Choose current or effect direction">${DIR.map((d,i)=>`<button class="direction ${chosenDir===i?'on':''}" data-direction="${i}" aria-label="${['North','East','South','West'][i]}" aria-pressed="${chosenDir===i}">${ARROWS[i]}</button>`).join('')}</div>`}
function goalProgress(){const m=MISSIONS[S.mission],p=progressState();if(m.extraction&&p.done>=p.total)return S.evacuated+' / 1 freed passengers extracted';if(m.operation&&S.sealed<S.required.seal)return S.sealed+' / '+S.required.seal+' relays connected · then '+m.goal;if(m.goal==='extinguish')return p.total+' fires remaining';if(m.goal==='boss')return (p.total-p.done)+' HP remaining';if(m.goal==='seal'&&p.done>=p.total)return 'Relays sealed → command exit';if(['reach','escort','push','deliver'].includes(m.goal))return {reach:'Reach the gold exit',escort:'Escort '+roleName(S.units.find(u=>u.id===S.escortId)),push:'Cart → gold pad',deliver:'Fragment → gold exit'}[m.goal];return p.done+' / '+p.total+' '+({clear:'disabled',collect:'recovered',hold:'rounds held',survive:'rounds',protect:'rounds',rescue:'rescued',seal:'sealed',disarm:'disarmed',plant:'beds planted',evacuate:'safe'}[m.goal]||'complete')}
function render(){if(recording||typeof document==='undefined')return;const m=MISSIONS[S.mission],act=CAMPAIGN.acts[m.act],u=S.units.find(v=>v.id===selected&&v.hp>0&&!v.escaped),r=ROLES[u?.role],moves=u&&mode==='move'&&!busy?moveOptions(u):new Map();let cells='';for(let y=0;y<height();y++)for(let x=0;x<width();x++){const t=tile(x,y),o=obj(x,y),p=unit(x,y),k=key(x,y),target=mode==='act'&&canAct(u,x,y),valid=inside(x,y);if(!valid&&!target){cells+='<div class="void-cell" aria-hidden="true"></div>';continue}const route=moves.get(k);cells+=`<button class="cell ${t} ${isGoal(x,y)&&t!=='goal'?'goal':''} ${!valid?'gap':''} ${route&&!blocked(x,y)?'move':''} ${target?'target':''} ${p?.id===selected&&!busy?'active':''} ${p?.team==='enemy'?'enemy':''}" style="--terrain:${TERRAIN_INFO[t]?.color||'#e9edd3'}" data-x="${x}" data-y="${y}" title="${esc(route?routeDescription(route):'Right-click or hold to inspect')}" aria-label="${coordinate(x,y)}, ${esc(p?roleName(p)+', '+p.hp+' HP':o?OBJECT_INFO[o]?.name:TERRAIN_INFO[t]?.name)}${route?', '+esc(routeDescription(route)):''}">${terrainArt(x,y)}${o?`<span class="object">${objectArt(o)}</span>${['fan','spring','mirror'].includes(o)?`<span class="mechanism-direction">${ARROWS[S.dirs[k]??1]}</span>`:''}`:''}${p?unitArt(p):''}${o==='bomb'?'<span class="fuse">'+(S.bombs.find(b=>b.x===x&&b.y===y)?.fuse||1)+'</span>':''}${p&&p.id===S.targetId?'<span class="boss-mark">◆</span>':''}${p?.id===S.escortId&&m.goal==='escort'?'<span class="boss-mark">✦</span>':''}</button>`}
 document.body.classList.toggle('quiet-motion',quietMotion);
 const progress=progressState(),pct=progress.total?Math.min(100,progress.done/progress.total*100):0;
 document.getElementById('app').innerHTML=`<header class="battle-header" ${modal||busy?'inert':''}><div class="battle-title"><i aria-hidden="true">≋</i><h1>${esc(m.title)}</h1></div><nav><button class="quiet" id="scenario">Scenario info</button><button class="quiet" id="help">Help</button><button class="quiet" id="chapters">Campaign</button></nav></header><main class="battle-shell" ${modal||busy?'inert':''}><div class="battle-layout"><section class="board-area" aria-label="Battlefield"><div class="board-wrap" data-biome="${m.act}"><div class="board weather-${S.weather}" style="--cols:${width()};--rows:${height()};--ratio:${width()/height()}">${cells}</div></div></section><aside class="battle-sidebar"><section class="objective-card"><h2>Objective</h2><p class="objective">${esc(objectiveText())}</p><div class="progress"><span style="width:${pct}%"></span></div><div class="objective-progress">${esc(goalProgress())}</div></section>${u?`<section class="selected-panel"><div class="selected-identity"><span class="portrait" style="color:${r.color}">${portrait(u.role)}</span><div><h2>${esc(roleName(u))}</h2><p>${esc(r.title)} · ${u.hp} HP</p></div></div><p class="ability">${esc(r.desc)}</p>${mode==='act'?directionsHTML(u):''}${u&&mode==='act'&&GLOBAL_ACTIONS.includes(r.action)?'<button class="primary global-activate" id="globalactivate">Apply '+esc(r.ability)+'</button>':''}${pending?'<div class="pending-help">Choose the destination tile.<button class="quiet" id="cancelpending">Cancel</button></div>':''}${interactable(u).map(([x,y])=>`<button class="action interaction" data-interact="${x},${y}" ${u.acted?'disabled':''}>${esc(OBJECT_INFO[obj(x,y)].name)} <span>${coordinate(x,y)}</span></button>`).join('')}</section>`:''}${inspectMode?'<div class="inspection-mode"><span>Tap a tile to inspect.</span><button class="quiet" id="inspect">Done</button></div>':''}<div class="control-dock"><button class="action ${mode==='move'?'on':''}" id="move" ${!movementLeft(u)?'disabled':''}>Move${u?' · '+movementLeft(u):''}</button><button class="action ${mode==='act'?'on':''}" id="ability" ${!u||u.acted?'disabled':''}>${esc(r?.ability||'Ability')}${u?.acted?' ✓':''}</button><button class="quiet undo-control" id="undo" aria-label="Undo last action" ${!history.length?'disabled':''}><span aria-hidden="true">↶</span><span class="undo-label"> Undo</span></button><button class="primary" id="end">End round</button></div></aside></div></main>${modal?modalHTML():''}${busy?'<div class="playback-status" role="status">'+esc(phaseLabel)+'</div>':''}`;
 attachCellControls();bind('scenario',()=>{modal='scenario';redraw()});bind('help',()=>{modal='help';redraw()});bind('inspect-help',()=>{inspectMode=true;modal=null;pending=null;mode='move';redraw()});bind('speed',cycleSpeed);bind('motion',toggleMotion);bind('chapters',()=>{modal='chapters';campaignAct=m.act;redraw()});bind('codex',()=>{modal='codex';redraw()});bind('briefing',()=>{modal='brief';redraw()});bind('close',()=>{modal=null;redraw()});bind('dismiss',()=>{modal=null;redraw()});bind('guide-motion',toggleMotion);bind('start',()=>{modal=null;redraw();playAction(beginBattle)});bind('retry',()=>load(S.mission));bind('next',()=>load(Math.min(99,S.mission+1)));bind('restart',()=>{modal='restart';redraw()});bind('end',()=>playAction(endTurn));bind('undo',()=>playAction(undoAction));bind('move',()=>{mode='move';pending=null;redraw()});bind('quickmove',()=>{mode='move';pending=null;redraw()});bind('ability',()=>{mode='act';redraw()});bind('quickact',()=>{mode='act';redraw()});bind('globalactivate',()=>playAction(()=>act(u,u.x,u.y)));bind('cancelpending',()=>{pending=null;redraw()});bind('inspect',()=>{inspectMode=!inspectMode;pending=null;mode='move';redraw()});bind('zoom',()=>{mobileZoom=!mobileZoom;redraw()});
 document.querySelectorAll('[data-unit]').forEach(el=>el.onclick=()=>{modal=null;selectUnit(el.dataset.unit)});document.querySelectorAll('[data-direction]').forEach(el=>el.onclick=()=>setDirection(+el.dataset.direction));document.querySelectorAll('[data-weather]').forEach(el=>el.onclick=()=>{weatherChoice=el.dataset.weather;redraw()});document.querySelectorAll('[data-interact]').forEach(el=>el.onclick=()=>playAction(()=>interact(...el.dataset.interact.split(',').map(Number))));document.querySelectorAll('[data-chapter]').forEach(el=>el.onclick=()=>load(+el.dataset.chapter));document.querySelectorAll('[data-act]').forEach(el=>el.onclick=()=>{campaignAct=+el.dataset.act;redraw()});document.querySelectorAll('[data-codextab]').forEach(el=>el.onclick=()=>{encyclopediaTab=el.dataset.codextab;encyclopediaSearch='';redraw()});const search=document.getElementById('campaignsearch');if(search)search.oninput=()=>{campaignSearch=search.value;filterCampaign()};const codexsearch=document.getElementById('codexsearch');if(codexsearch)codexsearch.oninput=()=>{encyclopediaSearch=codexsearch.value;document.querySelectorAll('[data-guide-name]').forEach(el=>el.hidden=!el.dataset.guideName.includes(encyclopediaSearch.toLowerCase()))};fitBoard();
}
function fitBoard(){const board=document.querySelector('.board'),area=document.querySelector('.board-area');if(!board||!area)return;const mobile=window.innerWidth<=700;if(mobile){board.style.width='100%';board.style.height='auto';return}const gap=3,availableW=area.clientWidth-14,availableH=area.clientHeight-14,cell=Math.max(8,Math.floor(Math.min((availableW-gap*(width()-1))/width(),(availableH-gap*(height()-1))/height())));board.style.width=(cell*width()+gap*(width()-1))+'px';board.style.height=(cell*height()+gap*(height()-1))+'px'}
if(typeof window!=='undefined')window.addEventListener('resize',fitBoard);
function filterCampaign(){const q=campaignSearch.toLowerCase();document.querySelectorAll('[data-mission-search]').forEach(el=>el.hidden=!el.dataset.missionSearch.includes(q))}
function campaignHTML(){const act=CAMPAIGN.acts[campaignAct];return `<h2>Campaign</h2><div class="act-tabs">${CAMPAIGN.acts.map((a,i)=>`<button class="act-tab ${i===campaignAct?'on':''}" data-act="${i}" title="${esc(a.title)}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><h3 class="campaign-act-name">${esc(act.title)}</h3><input id="campaignsearch" class="search" placeholder="Filter this act by title, objective or role…" value="${esc(campaignSearch)}" aria-label="Filter missions"><div class="mission-grid">${MISSIONS.filter(m=>m.act===campaignAct).map(m=>`<button class="mission-card" data-chapter="${m.index}" data-mission-search="${esc((m.title+' '+m.goal+' '+m.crew.map(r=>ROLES[r].title).join(' ')).toLowerCase())}" ${campaignSearch&&!((m.title+' '+m.goal+' '+m.crew.map(r=>ROLES[r].title).join(' ')).toLowerCase().includes(campaignSearch.toLowerCase()))?'hidden':''}>${missionMap(m)}<span class="mission-number">${completed.includes(m.index)?'✓':String(m.index+1).padStart(3,'0')}</span><div><strong>${esc(m.title)}</strong><span class="tiny">${m.width} × ${m.height} · ${m.shape} · ${m.crew.length} crew · ${m.goal}</span><span class="mission-roster">${m.crew.map(r=>`<i title="${esc(ROLES[r].title)}" style="color:${ROLES[r].color}">${ROLES[r].icon}</i>`).join('')}</span></div></button>`).join('')}</div><button class="quiet" id="close">Back to the field</button>`}
function codexHTML(){const cats={crew:ROLES,enemies:ENEMIES,objects:OBJECT_INFO,terrain:TERRAIN_INFO},data=cats[encyclopediaTab];return `<div class="eyebrow">FIELD GUIDE / NO STAT PROGRESSION</div><h2>Know the field.</h2><div class="act-tabs">${Object.entries(cats).map(([id,rows])=>`<button class="act-tab ${encyclopediaTab===id?'on':''}" data-codextab="${id}">${id} · ${Object.keys(rows).length}</button>`).join('')}</div><p>Each crew member has one distinctive ability, 3 HP and 3 move points. Move in stages, then act; or act first, then move. Acting after movement closes movement. Right-click or hold any tile for local rules.</p><input id="codexsearch" class="search" placeholder="Search the field guide…" aria-label="Search the field guide"><div class="guide-grid">${Object.entries(data).map(([id,r])=>`<article class="guide-card" data-guide-name="${esc((id+' '+r.name+' '+(r.title||'')).toLowerCase())}"><span class="guide-symbol illustrated" style="color:${r.color||'#668b7a'}">${guideArt(id,encyclopediaTab)}</span><div><h3>${esc(r.title?r.name+' / '+r.title:r.name)}</h3><p>${esc(r.desc||r.text)}</p>${r.lore?'<p class="tiny">'+esc(r.lore)+'</p>':''}</div></article>`).join('')}</div><div class="guide-settings"><button class="quiet" id="guide-motion" aria-pressed="${quietMotion}">${quietMotion?'Enable ambient motion':'Reduce ambient motion'}</button><span class="tiny">Keyboard: 1–9 crew · M move · A ability · Z undo · Enter end round · Esc deselect</span></div><button class="quiet" id="close">Back to the field</button>`}
function inspectHTML(x,y){const d=inspectData(x,y),p=unit(x,y),o=obj(x,y);return `<div class="inspection-art">${p?portrait(p.role,p.team==='enemy'):o?objectArt(o):guideArt(tile(x,y),'terrain')}</div><div class="eyebrow">FIELD INSPECTION / ${d.coordinate}</div><h2>Know your ground.</h2>${d.layers.map((l,i)=>`<section class="inspect-entry"><div class="eyebrow">${i===d.layers.length-1?'TERRAIN':i===0&&unit(x,y)?'UNIT':'OBJECT'}</div><h3>${esc(l.name)}</h3><p>${esc(l.text)}</p></section>`).join('')}<p class="tiny">Inspection never spends a move or action.</p><button class="primary" id="close">Back to the field →</button>`}
function scenarioHTML(){const m=MISSIONS[S.mission],act=CAMPAIGN.acts[m.act],crew=S.units.filter(a=>a.team==='ally'&&!a.drone);return `<div class="eyebrow">Mission ${S.mission+1} · Round ${S.round}${S.weather!=='clear'?' · '+esc(S.weather):''}</div><h2>${esc(m.title)}</h2><p>${esc(m.brief)}</p><details><summary>Campaign story</summary><h3>${esc(act.title)}</h3><p>${esc(act.summary)}</p></details><h3>Crew status</h3><div class="scenario-crew">${crew.map(a=>`<button class="unit-card ${a.id===selected?'selected':''} ${a.hp<=0||a.escaped?'dead':''}" data-unit="${a.id}" ${a.hp<=0||a.escaped?'disabled':''}><span class="portrait">${portrait(a.role)}</span><span><strong>${esc(roleName(a))}</strong><span class="tiny">${esc(ROLES[a.role]?.title||'Passenger')}</span><span class="tiny">${a.escaped?'Safe':a.hp<=0?'Disabled':a.hp+' HP · '+movementLeft(a)+' move · '+(a.acted?'action used':'action ready')}</span></span></button>`).join('')}</div><details><summary>Radio history</summary>${S.log.map(t=>`<p>${esc(t)}</p>`).join('')}</details><details><summary>Field notes</summary><p>${esc(m.tip)}</p>${crew.map(a=>'<p><strong>'+esc(roleName(a))+'</strong> · '+esc(ROLES[a.role]?.lore||'')+'</p>').join('')}</details><button class="quiet" id="restart">Restart mission</button> <button class="primary" id="close">Back to battle</button>`}
function helpHTML(){return `<h2>How to play</h2><section class="help-entry"><h3>Move and act</h3><p>Select a unit on the field. Green tiles are reachable; gold tiles are ability targets. Use Move or the unit’s ability button to switch.</p><p>Move in stages by choosing stops, or choose a distant destination. Hover to preview the route. Each unit has 3 move points; forced movement from ice and currents is free.</p><p>You can act first and then move, or move and then act. Acting after movement ends movement for that round. Click the selected unit again, click outside its range, or press Escape to deselect it.</p></section><section class="help-entry"><h3>Inspect the field</h3><p>Right-click or hold a tile to read its unit, object, and terrain rules. On touch screens, you can also turn on inspection below, then tap a tile.</p><button class="quiet" id="inspect-help">Inspect tiles</button></section><section class="help-entry"><h3>Controls</h3><p>1–9 selects crew · M moves · A uses an ability · Z undoes · Enter ends the round · Escape closes a panel or deselects.</p><div class="help-preferences"><button class="quiet" id="speed">Animation speed · ${visualSpeed}×</button><button class="quiet" id="guide-motion" aria-pressed="${quietMotion}">${quietMotion?'Enable ambient motion':'Reduce ambient motion'}</button></div></section><button class="quiet" id="codex">Field guide</button> <button class="primary" id="close">Back to battle</button>`}
function modalHTML(){const m=MISSIONS[S.mission],act=CAMPAIGN.acts[m.act];let body='',wide=false;if(modal==='chapters'){body=campaignHTML();wide=true}if(modal==='codex'){body=codexHTML();wide=true}if(modal==='scenario')body=scenarioHTML();if(modal==='help')body=helpHTML();if(modal==='inspect')body=inspectHTML(inspectCell.x,inspectCell.y);if(modal==='brief')body=`${chapterVista(m.act)}<div class="eyebrow">${m.place} / BRIEFING</div><h2>${esc(m.title)}</h2><p>${esc(m.brief)}</p><div class="brief-speaker"><span class="portrait" style="color:${ROLES[m.speaker]?.color}">${ROLES[m.speaker]?portrait(m.speaker):'☼'}</span><p><strong>${esc(ROLES[m.speaker]?.name||m.speaker)}</strong><br>“${esc(m.line)}”</p></div><div class="hint">${esc(objectiveText())}</div><div class="brief-roster">${m.crew.map(r=>`<span>${portrait(r)}<span><strong>${esc(ROLES[r].name)}</strong>${esc(ROLES[r].title)}</span></span>`).join('')}</div>${m.event?'<p class="tiny">Field warning: conditions or reinforcements may change during this mission. Listen to the crew’s radio.</p>':''}<button class="primary" id="start">Deploy the crew →</button>`;if(modal==='restart')body=`<div class="eyebrow">A FRESH APPROACH</div><h2>Try another way?</h2><p>Restart this battle with the original crew and terrain. All 100 missions remain available.</p><button class="primary" id="retry">Restart battle</button> <button class="quiet" id="close">Keep playing</button>`;if(modal==='loss')body=`<div class="eyebrow">THE CURRENT TURNS</div><h2>Another way exists.</h2><p>${esc(S.failed||'The crew is down. Use cover and terrain, and try a different route. Every role has a different way to help.')}</p><button class="primary" id="retry">Try again →</button> <button class="quiet" id="chapters">Campaign</button>`;if(modal==='win')body=`<div class="victory-seal" aria-hidden="true">✧</div><div class="eyebrow">${S.mission===99?'THE HUNDRED SHORES / THE END':'MISSION '+String(S.mission+1).padStart(3,'0')+' COMPLETE'}</div><h2>${S.mission===99?'And then, rain.':'A little hope restored.'}</h2><p>${esc(m.debrief)}</p><div class="brief-speaker"><span class="portrait" style="color:${ROLES[m.speaker]?.color}">${ROLES[m.speaker]?portrait(m.speaker):'◇'}</span><p><strong>${esc(ROLES[m.speaker]?.name||m.speaker)}</strong><br>${esc(S.mission===99?'There is no last shore. Only the next one.':'We made a way through. Let us keep it open.')}</p></div><p class="tiny">${alive('ally').length} crew standing · ${S.round} rounds · completion saved on this device</p>${S.mission<99?'<button class="primary" id="next">Next mission →</button>':''} <button class="quiet" id="chapters">Campaign</button> <button class="quiet" id="retry">Replay</button>`;return `<div class="overlay"><section class="modal ${wide?'wide':''} modal-${modal}" role="dialog" aria-modal="true" aria-label="${modal}">${wide||['inspect','scenario','help'].includes(modal)?'<div class="modal-tools"><button id="dismiss" class="modal-dismiss" aria-label="Close panel">×</button></div>':''}${body}</section></div>`}
